"""Write briefs/README.md: every brief in tracker order (section, then entry), with its stage.

GitHub shows this below the briefs/ file list. Run after any tracker or brief change:
    python3 scripts/build_brief_index.py
"""
import csv, os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
rows = list(csv.DictReader(open(f'{ROOT}/tracker.csv', encoding='utf-8')))
out = ['# Briefs (in tracker order)', '',
       'Generated by `scripts/build_brief_index.py` from `tracker.csv`. Do not edit by hand.', '']
section = None
for r in rows:
    if not os.path.exists(f"{ROOT}/briefs/{r['id']}.md"):
        continue
    if r['section'] != section:
        section = r['section']
        out += ['', f"## {r['section_no']}. {section}", '', '| Entry | Type | Stage |', '| --- | --- | --- |']
    out.append(f"| [{r['title']}]({r['id']}.md) | {r['type']} | {r['status']} |")
open(f'{ROOT}/briefs/README.md', 'w', encoding='utf-8').write('\n'.join(out) + '\n')
